import{_ as n,o as s,c as t,ah as r}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Numérisation","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/gestion-documentaire/numerisation.md","filePath":"src/guide/gestion-documentaire/numerisation.md"}'),a={name:"guide/gestion-documentaire/numerisation.md"};function o(i,e,u,l,p,c){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="numerisation" tabindex="-1">Numérisation <a class="header-anchor" href="#numerisation" aria-label="Permalink to &quot;Numérisation&quot;">​</a></h1><p>ERA fait entrer le papier de deux façons : la <strong>photo des pages au téléphone</strong>, pour un document qu&#39;on vous remet au guichet, et la <strong>reprise d&#39;archives</strong>, pour un carton entier de dossiers anciens.</p><p>Dans les deux cas, ERA <strong>lit le texte</strong> des images pour qu&#39;on retrouve ensuite le document par son contenu. Cette lecture se fait dans votre navigateur : le document ne quitte jamais l&#39;établissement.</p><div class="info custom-block"><p class="custom-block-title">Première lecture</p><p>La première fois qu&#39;un navigateur lit un texte, il télécharge le moteur de lecture et les modèles de français et d&#39;anglais (quelques Mo), puis les garde en mémoire. Cette première lecture demande donc une connexion internet et prend un peu plus de temps.</p></div><p>La lecture rend les documents <strong>cherchables</strong> et <strong>suggère les personnes</strong> dont le nom apparaît. Elle ne remplit pas les champs à votre place : relisez toujours ce que vous classez.</p><h2 id="photographier-un-document-au-telephone" tabindex="-1">Photographier un document au téléphone <a class="header-anchor" href="#photographier-un-document-au-telephone" aria-label="Permalink to &quot;Photographier un document au téléphone&quot;">​</a></h2><ol><li>Dans le dossier, cliquez sur <strong>Déposer</strong> à côté du type concerné.</li><li>Choisissez <strong>Photos des pages</strong>.</li><li>Cliquez sur <strong>Prendre une photo</strong> et photographiez la première page, à plat et bien éclairée. Recommencez pour chaque page, dans l&#39;ordre. Le bouton <strong>Choisir des images</strong> prend des photos déjà dans le téléphone.</li><li>Chaque page s&#39;affiche en vignette, numérotée. La croix retire une page ratée. Le texte de chaque page est lu pendant que vous continuez.</li><li>Complétez l&#39;intitulé, la date et les notes si besoin, puis cliquez sur <strong>Déposer</strong>.</li></ol><p>Les pages, 20 au plus, sont réunies en <strong>un seul PDF</strong> au format A4, dans l&#39;ordre où vous les avez prises. Le document suit ensuite le même chemin que tout dépôt : validé tout de suite si vous pouvez le valider et que la case est cochée, sinon à vérifier.</p><p>Avec le mode <strong>Un fichier</strong>, le texte d&#39;une image déposée est lu de la même façon. Le texte des PDF n&#39;est pas lu.</p><h2 id="retrouver-un-document-par-son-contenu" tabindex="-1">Retrouver un document par son contenu <a class="header-anchor" href="#retrouver-un-document-par-son-contenu" aria-label="Permalink to &quot;Retrouver un document par son contenu&quot;">​</a></h2><p>Sur la page <strong>Documents</strong>, le champ <strong>Rechercher dans les documents</strong> cherche aussi dans le texte lu. Tapez par exemple un lieu de naissance ou un numéro d&#39;acte pour retrouver les documents qui le portent.</p><h2 id="la-reprise-d-archives" tabindex="-1">La reprise d&#39;archives <a class="header-anchor" href="#la-reprise-d-archives" aria-label="Permalink to &quot;La reprise d&#39;archives&quot;">​</a></h2><p>Une <strong>campagne de reprise</strong> fait entrer une archive papier en nombre, puis la classe document par document. Elle est réservée à un administrateur et au gestionnaire documentaire, depuis l&#39;espace <strong>Documents</strong> → <strong>Reprise d&#39;archives</strong>.</p><h3 id="creer-une-campagne" tabindex="-1">Créer une campagne <a class="header-anchor" href="#creer-une-campagne" aria-label="Permalink to &quot;Créer une campagne&quot;">​</a></h3><p>Sous <strong>Nouvelle campagne</strong>, donnez-lui le nom de l&#39;archive qu&#39;elle fait entrer (par exemple « Dossiers d&#39;inscription 2019-2020 »), ajoutez des notes si besoin, puis cliquez sur <strong>Créer la campagne</strong>.</p><p>La liste des <strong>Campagnes</strong> indique, pour chacune, combien de numérisations elle contient et combien restent à classer.</p><h3 id="faire-entrer-les-numerisations" tabindex="-1">Faire entrer les numérisations <a class="header-anchor" href="#faire-entrer-les-numerisations" aria-label="Permalink to &quot;Faire entrer les numérisations&quot;">​</a></h3><p>Numérisez le carton avec le scanner de l&#39;établissement ou un téléphone, puis, dans la campagne, cliquez sur <strong>Choisir les numérisations</strong> et sélectionnez tous les fichiers d&#39;un coup : PDF ou images, 10 Mo chacun au plus.</p><p>ERA lit le texte de chaque image puis l&#39;envoie, une par une. Le compteur indique où il en est. Gardez la page ouverte jusqu&#39;à la fin. Si une numérisation n&#39;a pas pu être envoyée, le compteur le signale : choisissez-la à nouveau.</p><p>Les numérisations entrées attendent dans <strong>À classer</strong>. Tant qu&#39;elles ne sont pas classées, elles n&#39;ont ni type ni dossier : seuls un administrateur et le gestionnaire documentaire les voient, et elles n&#39;apparaissent ni dans les dossiers ni dans les documents à vérifier.</p><h3 id="classer-une-numerisation" tabindex="-1">Classer une numérisation <a class="header-anchor" href="#classer-une-numerisation" aria-label="Permalink to &quot;Classer une numérisation&quot;">​</a></h3><p>La campagne affiche la première numérisation à classer, avec le texte lu dessus sous <strong>Texte lu sur la page</strong>. Les numéros au-dessus permettent d&#39;en choisir une autre.</p><ol><li>Choisissez le <strong>Type de document</strong>.</li><li>Si le type se range dans le dossier d&#39;un élève ou d&#39;un employé, ERA propose les personnes dont le nom figure sur la page, et coche la première. Vérifiez-la, ou cherchez une autre personne par son nom avec la loupe.</li><li>Complétez si besoin l&#39;<strong>Intitulé</strong> et la <strong>Date du document</strong>.</li><li>Si vous pouvez valider ce type, la case <strong>Je l&#39;ai vérifié : le valider tout de suite</strong> est cochée. Sinon, le document reste à vérifier par ceux qui valident ce type.</li><li>Cliquez sur <strong>Classer</strong>. La numérisation suivante s&#39;affiche.</li></ol><p>Pour un élève, ERA propose ceux dont le <strong>nom et le premier prénom</strong> figurent sur la page, ou dont le numéro matricule y figure quand l&#39;établissement en utilise. Pour un employé, il faut son nom complet. Les accents et les majuscules ne comptent pas. Un nom de famille seul ne suffit pas : il désigne trop souvent plusieurs élèves.</p><p>Les dernières numérisations classées s&#39;affichent en bas de la campagne, avec leur type, leur personne et leur statut. Une fois classée, une numérisation est un document comme les autres, dans son dossier.</p>',25)])])}const g=n(a,[["render",o]]);export{m as __pageData,g as default};
